import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import API from '../api/axios';

const ComplaintForm = () => {
  const [formData, setFormData] = useState({
    category: 'Electrical', title: '', description: '', location: ''
  });
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const data = new FormData();
    data.append('category', formData.category);
    data.append('title', formData.title);
    data.append('description', formData.description);
    data.append('location', formData.location);
    if (file) data.append('image', file);

    try {
      await API.post('/complaints', data, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      alert('Complaint raised successfully!');
      navigate('/my-complaints');
    } catch (err) {
      alert(err.response?.data?.message || 'Error submitting complaint.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto px-4 py-8">
      <div className="bg-white p-8 rounded-xl shadow-md border border-slate-200">
        <h2 className="text-2xl font-bold text-slate-900 mb-6">File Maintenance Complaint</h2>

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="text-sm font-semibold text-slate-700">Category</label>
            <select
              className="w-full mt-1 px-3 py-2 border rounded-md bg-white"
              value={formData.category}
              onChange={(e) => setFormData({ ...formData, category: e.target.value })}
            >
              <option>Electrical</option>
              <option>Plumbing</option>
              <option>Carpentry</option>
              <option>IT / Network</option>
              <option>Cleanliness</option>
            </select>
          </div>

          <div>
            <label className="text-sm font-semibold text-slate-700">Issue Title</label>
            <input
              type="text" required placeholder="e.g. Broken Light Switch"
              className="w-full mt-1 px-3 py-2 border rounded-md"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
            />
          </div>

          <div>
            <label className="text-sm font-semibold text-slate-700">Specific Location</label>
            <input
              type="text" required placeholder="e.g. Lab 3, CSE Block 2nd Floor"
              className="w-full mt-1 px-3 py-2 border rounded-md"
              value={formData.location}
              onChange={(e) => setFormData({ ...formData, location: e.target.value })}
            />
          </div>

          <div>
            <label className="text-sm font-semibold text-slate-700">Detailed Description</label>
            <textarea
              required rows="4" placeholder="Explain the exact maintenance issue..."
              className="w-full mt-1 px-3 py-2 border rounded-md"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            />
          </div>

          <div>
            <label className="text-sm font-semibold text-slate-700">Attach Photo Proof (Optional)</label>
            <input
              type="file" accept="image/*"
              className="w-full mt-1 text-sm text-slate-500"
              onChange={(e) => setFile(e.target.files[0])}
            />
          </div>

          <button
            type="submit" disabled={loading}
            className="w-full bg-sky-600 hover:bg-sky-700 text-white font-bold py-2.5 rounded-lg transition"
          >
            {loading ? 'Submitting...' : 'Submit Complaint'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default ComplaintForm;
